import 'package:firebase_core/firebase_core.dart';

/// Replace this file by running:
/// `flutterfire configure --platforms=android,ios --out=lib/firebase_options.dart`
///
/// The generated file contains platform identifiers, not credentials, and
/// should be committed.
class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform {
    throw UnsupportedError(
      'Firebase has not been configured for this template yet. '
      'Run flutterfire configure and commit the generated '
      'lib/firebase_options.dart file.',
    );
  }
}
